describe("doctests of sympy.polys.solvers", () => {
  it("eqs_to_matrix(eqs_coeff, eqs_rhs, [x, y], ZZ)", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(eqsToMatrix([new Map([[x, 1], [y, 1]]), new Map([[x, 1], [y, -1]])], [0, -1], [x, y], ZZ))).toBe('DomainMatrix([[1, 1, 0], [1, -1, 1]], (2, 3), ZZ)');
  });
  // the arguments do not type-check against the public API
  //   solve_lin_sys(eqs_ring, ring)
  //   => {x: MPQ(1,1), y: MPQ(1,1)}
  it.todo("solve_lin_sys(eqs_ring, ring)");
  // the arguments do not type-check against the public API
  //   solve_lin_sys(eqs_ring, ring, _raw=False)
  //   => {x: 1, y: 1}
  it.todo("solve_lin_sys(eqs_ring, ring, _raw=False)");
  // the arguments do not type-check against the public API
  //   solve_lin_sys(eqs_ring, ring)
  //   => {x: 0, y: 0}
  it.todo("solve_lin_sys(eqs_ring, ring) (2)");
  // a result object that did not come from the library
  //   eqs_ring
  //   => [x - y, x + a*y]
  it.todo("eqs_ring");
});

